<script setup>
import{shallowRef,ref,onUnmounted}from'vue';const props=defineProps({color:String});const emit=defineEmits(['record','start']);const drawn=shallowRef([]),active=ref(false),completed=shallowRef([]);let points=[],frame=0,element,activePointer;
function xy(e){const r=element.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function begin(e){if(active.value||(e.button!==0&&e.button!==2))return;e.preventDefault();completed.value=[];emit('start');element=e.currentTarget;activePointer=e.pointerId;points=[xy(e)];drawn.value=points.slice();active.value=true;try{element.setPointerCapture(e.pointerId)}catch{}}
function move(e){if(!active.value)return;const events=e.getCoalescedEvents?.()||[];for(const sample of events.length?events:[e]){const p=xy(sample),prev=points.at(-1);if(Math.hypot(p.x-prev.x,p.y-prev.y)<1)continue;if(points.length<1500)points.push(p);}if(!frame)frame=requestAnimationFrame(()=>{drawn.value=points.slice();frame=0})}
function end(e){if(!active.value||e.pointerId!==activePointer)return;const p=xy(e);points.push(p);active.value=false;if(frame)cancelAnimationFrame(frame);frame=0;drawn.value=points.slice();const stroke=points.filter((p,i)=>i%Math.max(1,Math.floor(points.length/256))===0||i===points.length-1).map(p=>({...p}));completed.value=[stroke];drawn.value=[];emit('record',completed.value.map(s=>s.map(p=>({...p}))));}
function cancel(){if(!active.value)return;active.value=false;points=[];drawn.value=[];emit('record',completed.value)}
window.addEventListener('pointerup',end);onUnmounted(()=>{window.removeEventListener('pointerup',end);if(frame)cancelAnimationFrame(frame)});
</script>
<template><div class="draw gesture-pad" data-multi="false" :data-strokes="completed.length" @pointerdown="begin" @pointermove="move" @pointerup="end" @pointercancel="cancel" @contextmenu.prevent><span v-if="!drawn.length&&!completed.length">按住左键或右键一笔画完，松开完成；再次绘制会替换当前轨迹</span><svg aria-hidden="true"><polyline v-for="(stroke,i) in completed" :key="i" :points="stroke.map(p=>`${p.x},${p.y}`).join(' ')" fill="none" :stroke="color||'#208b91'" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><polyline :points="drawn.map(p=>`${p.x},${p.y}`).join(' ')" fill="none" :stroke="color||'#4f66e8'" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg><strong>{{active?'正在录制…':completed.length?'已录制':''}}</strong></div></template>
